  const DEFAULT_AREA_CODE_CELL = "Z1";
  const defaultAreaCode = sheet.getRange(DEFAULT_AREA_CODE_CELL).getValue().toString().replace(/\D/g, "");

  // Column indices (0-based). Adjust if your layout differs.
  const COL = {
    timestamp:     0,  // A - raw timestamp
    name:          1,  // B
    email:         2,  // C
    joinedBefore:  6,  // G - cleaned Yes/No
    phone:         7,  // H - cleaned phone
    timestamp_c:   8,  // I - cleaned timestamp
    park:          9,  // J - cleaned park
    reviewFlag:   15,  // P - review flag (0-based = col 16)
