  const outputHeaders = ["CleanedJoined", "CleanedPhone", "CleanedTimestamp", "CleanedPark", "Superseded", "Conflicts"];
  outputHeaders.forEach((h, i) => {
    sheet.getRange(1, OUT.cleanedJoined + i + 1).setValue(h);
  });

  // ── Helpers ──────────────────────────────────────────────────────────────

  function normalizePhone(raw) {
    if (!raw) return "";
    const digits = raw.toString().replace(/\D/g, "");
    if (digits.length === 10) return digits;
    if (digits.length === 11 && digits[0] === "1") return digits.slice(1);
    if (digits.length === 7 && defaultAreaCode.length === 3) return defaultAreaCode + digits;
    return "";
  }

  function normalizeEmail(raw) {
    return raw ? raw.toString().trim().toLowerCase() : "";
  }

  function normalizeName(raw) {
    return raw ? raw.toString().trim().toLowerCase().replace(/\s+/g, " ") : "";
  }

  function parseTimestamp(val) {
    if (!val) return null;
    if (val instanceof Date) return val;
    const d = new Date(val);
    return isNaN(d.getTime()) ? null : d;
  }

  function withinMinutes(ts1, ts2, minutes) {
    if (!ts1 || !ts2) return false;
    return Math.abs(ts1.getTime() - ts2.getTime()) <= minutes * 60 * 1000;
  }

  function completenessScore(row) {
    const fields = [
      row[COL.joinedBefore],
      normalizePhone(row[COL.phone]),
      row[COL.park],
      normalizeEmail(row[COL.email]),
    ];
    return fields.filter(f => f && f.toString().trim() !== "" && f.toString().trim() !== "REVIEW").length;
  }

  function getConflicts(rows) {
    const fieldNames = ["JoinedBefore", "Phone", "PreferredPark", "Email"];
    const getters = [
      r => r[COL.joinedBefore],
      r => normalizePhone(r[COL.phone]),
      r => r[COL.park],
      r => normalizeEmail(r[COL.email]),
    ];
    const conflicting = [];
    fieldNames.forEach((name, i) => {
      const values = rows.map(r => (getters[i](r) || "").toString().trim().toLowerCase());
      const unique = [...new Set(values.filter(v => v !== "" && v !== "review"))];
      if (unique.length > 1) conflicting.push(name);
    });
    return conflicting.join(", ");
