      cleanedJoined:    r.data[COL.joinedBefore] || "",
      cleanedPhone:     normalizePhone(r.data[COL.phone]),
      cleanedTimestamp: r.data[COL.timestamp_c] || "",
      cleanedPark:      r.data[COL.park] || "",
      superseded:       "",
      conflicts:        "",
