    const o = output[r.sheetRow];
    sheet.getRange(r.sheetRow, OUT.cleanedJoined + 1, 1, 6).setValues([[
      o.cleanedJoined,
      o.cleanedPhone,
      o.cleanedTimestamp,
      o.cleanedPark,
      o.superseded,
      o.conflicts,
    ]]);
  });

  SpreadsheetApp.getUi().alert("Done. Check columns Q–V for cleaned values, Superseded, and Conflicts.");
