---

Three things changed from the previous version.

Adding `CleanedEmail` shifted the output by one column — Superseded is now U→V and Conflicts is V→W, so the header check and the final `setValues` call both cover 7 columns instead of 6. Double-check that columns W and beyond are free before running.

The `underReview` flag is set on each row object at build time, and the group sort now uses `a.underReview - b.underReview` as its first criterion. Since `false` coerces to 0 and `true` to 1, non-review rows sort to the front naturally. If every row in a group is under review, they all remain eligible and the score/timestamp tiebreakers apply as before — no group is left without a winner.

The email copy follows exactly the same guard as the other fields: winner email must pass `isUsable` and the target email must not.

Looking at the previous script, the header check already used `every` (all blank), so tweak 2 is actually already correct — but I'll keep it explicit and add a comment so it's clear. The main change is tweak 1: dropping `CleanedEmail` from OUT, shifting Superseded back to U and Conflicts to V, keeping the email copy logic in the superseded block, and tightening everything back to 6 columns.

```javascript
function cleanVolunteerData() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sheet = ss.getSheetByName("Responses");
  if (!sheet) { SpreadsheetApp.getUi().alert("Sheet 'Responses' not found."); return; }

  const data = sheet.getDataRange().getValues();
  const defaultAreaCode = sheet.getRange("Z1").getValue().toString().replace(/\D/g, "");

  const COL = {
    timestamp:    0,
    name:         1,
    email:        2,
    joinedBefore: 6,
    phone:        7,
    timestamp_c:  8,
    park:         9,
    reviewFlag:  15,  // P
  };

  const OUT = {
    cleanedJoined:    16,  // Q
    cleanedPhone:     17,  // R
    cleanedTimestamp: 18,  // S
    cleanedPark:      19,  // T
    superseded:       20,  // U
    conflicts:        21,  // V
  };

  // ── Helpers ───────────────────────────────────────────────────────────────

  const normalizePhone = raw => {
    const d = raw ? raw.toString().replace(/\D/g, "") : "";
    if (d.length === 10) return d;
    if (d.length === 11 && d[0] === "1") return d.slice(1);
    if (d.length === 7 && defaultAreaCode.length === 3) return defaultAreaCode + d;
    return "";
  };

  const normalizeEmail = raw => raw ? raw.toString().trim().toLowerCase() : "";
  const normalizeName  = raw => raw ? raw.toString().trim().toLowerCase().replace(/\s+/g, " ") : "";

  const parseTimestamp = val => {
    if (!val) return null;
    if (val instanceof Date) return val;
    const d = new Date(val);
    return isNaN(d.getTime()) ? null : d;
  };

  const withinMinutes = (t1, t2, mins) =>
    t1 && t2 && Math.abs(t1.getTime() - t2.getTime()) <= mins * 60 * 1000;

  const isUsable = v => v && v.toString().trim() !== "" && v.toString().trim().toUpperCase() !== "REVIEW";

  const isUnderReview = row => row[COL.reviewFlag].toString().trim().toUpperCase() === "REVIEW";

  const completenessScore = row =>
    [row[COL.joinedBefore], normalizePhone(row[COL.phone]), row[COL.park], normalizeEmail(row[COL.email])]
      .filter(isUsable).length;

  const getConflicts = rows => {
    const fields = [
      ["JoinedBefore", r => r[COL.joinedBefore]],
      ["Phone",        r => normalizePhone(r[COL.phone])],
      ["PreferredPark",r => r[COL.park]],
      ["Email",        r => normalizeEmail(r[COL.email])],
    ];
    return fields
      .filter(([, get]) => {
        const vals = [...new Set(rows.map(r => (get(r) || "").trim().toLowerCase()).filter(v => v && v !== "review"))];
        return vals.length > 1;
      })
      .map(([name]) => name)
      .join(", ");
  };

  // ── Build row objects ─────────────────────────────────────────────────────

  let nextGroupId = 0;
  const rows = data.slice(1).map((row, i) => ({
    sheetRow:    i + 2,
    data:        row,
    email:       normalizeEmail(row[COL.email]),
    name:        normalizeName(row[COL.name]),
    timestamp:   parseTimestamp(row[COL.timestamp_c]) || parseTimestamp(row[COL.timestamp]),
    score:       completenessScore(row),
    underReview: isUnderReview(row),
    groupId:     null,
  }));

  // ── Group by email OR (name + within 10 min) ──────────────────────────────

  const mergeGroups = (a, b) => {
    if (a.groupId === null && b.groupId === null) {
      a.groupId = b.groupId = nextGroupId++;
    } else if (a.groupId === null) {
      a.groupId = b.groupId;
    } else if (b.groupId === null) {
      b.groupId = a.groupId;
    } else if (a.groupId !== b.groupId) {
      const old = b.groupId;
      rows.forEach(r => { if (r.groupId === old) r.groupId = a.groupId; });
    }
  };

  for (let i = 0; i < rows.length; i++) {
    for (let j = i + 1; j < rows.length; j++) {
      const a = rows[i], b = rows[j];
      if ((a.email && b.email && a.email === b.email) ||
          (a.name  && b.name  && a.name  === b.name && withinMinutes(a.timestamp, b.timestamp, 10))) {
        mergeGroups(a, b);
      }
    }
  }

  // ── Write headers only if every cell in Q1:V1 is blank ───────────────────

  const headerRange = sheet.getRange(1, OUT.cleanedJoined + 1, 1, 6);
  if (headerRange.getValues()[0].every(cell => cell.toString().trim() === "")) {
    headerRange.setValues([["CleanedJoined","CleanedPhone","CleanedTimestamp","CleanedPark","Superseded","Conflicts"]]);
  }

  // ── Resolve groups: non-review first, then score desc, then timestamp desc ─

  const groups = {};
  rows.forEach(r => {
    if (r.groupId !== null) {
      (groups[r.groupId] = groups[r.groupId] || []).push(r);
    }
  });

  const winnerFields = {};
  Object.values(groups).forEach(group => {
    group.sort((a, b) =>
      a.underReview - b.underReview ||
      b.score - a.score ||
      (b.timestamp && a.timestamp ? b.timestamp.getTime() - a.timestamp.getTime() : 0)
    );
    const w = group[0].data;
    winnerFields[group[0].groupId] = {
      joined:    w[COL.joinedBefore],
      phone:     normalizePhone(w[COL.phone]),
      timestamp: w[COL.timestamp_c],
      park:      w[COL.park],
      email:     normalizeEmail(w[COL.email]),  // carried for copying, not output as own column
    };
  });

  // ── Build and write output (6 columns: Q–V) ───────────────────────────────

  const outputValues = rows.map(r => {
    const out = {
      joined:    r.data[COL.joinedBefore],
      phone:     normalizePhone(r.data[COL.phone]),
      timestamp: r.data[COL.timestamp_c],
      park:      r.data[COL.park],
      superseded:"",
      conflicts: "",
    };

    if (r.groupId !== null) {
      const group  = groups[r.groupId];
      const winner = group[0];
      const wf     = winnerFields[r.groupId];

      out.conflicts = getConflicts(group.map(g => g.data));

      if (r.sheetRow !== winner.sheetRow) {
        out.superseded = "SUPERSEDED";
        if (isUsable(wf.joined)    && !isUsable(out.joined))    out.joined    = wf.joined;
        if (isUsable(wf.phone)     && !isUsable(out.phone))     out.phone     = wf.phone;
        if (isUsable(wf.timestamp) && !isUsable(out.timestamp)) out.timestamp = wf.timestamp;
        if (isUsable(wf.park)      && !isUsable(out.park))      out.park      = wf.park;
        // Email copied into raw column C on superseded rows, not to a new output column
        if (isUsable(wf.email) && !isUsable(r.data[COL.email])) {
          sheet.getRange(r.sheetRow, COL.email + 1).setValue(wf.email);
        }
      }
    }

    return [out.joined, out.phone, out.timestamp, out.park, out.superseded, out.conflicts];
  });

  sheet.getRange(2, OUT.cleanedJoined + 1, outputValues.length, 6).setValues(outputValues);

  SpreadsheetApp.getUi().alert("Done. Columns Q-V updated on sheet 'Responses'.");
}
